mapper.select:
SELECT r.resume_sq AS resumeSq, r.user_sq AS userSq, u.user_nm AS name, r.resume_ttl AS jobTitle, COALESCE( ( SELECT FLOOR(SUM(TIMESTAMPDIFF(MONTH, c.career_start_dt, COALESCE(c.career_end_dt, CURDATE()))) / 12) FROM TBL_RESUME_CAREER_S c WHERE c.resume_sq = r.resume_sq ), 0 ) AS experienceYears,
CONCAT('/api/v1/files/', p.file_sq) AS profileImageUrl, r.resume_greeting_txt AS summary FROM TBL_RESUME_M r INNER JOIN TBL_USER_M u ON r.user_sq = u.user_sq LEFT JOIN tbl_user_profile_image_s p ON u.user_sq = p.user_sq
AND COALESCE( ( SELECT FLOOR(SUM(TIMESTAMPDIFF(MONTH, c.career_start_dt, COALESCE(c.career_end_dt, CURDATE()))) / 12) FROM TBL_RESUME_CAREER_S c WHERE c.resume_sq = r.resume_sq ), 0 ) >= #{req.experience}
AND r.resume_sq IN ( SELECT rss.resume_sq FROM TBL_RESUME_SKILL_SEARCH_S rss INNER JOIN TBL_SKILL_TAG_C st ON rss.skill_tag_sq = st.skill_tag_sq WHERE LOWER(st.skill_tag_nm) IN
LOWER(TRIM(#{skill}))
)
ORDER BY r.resume_sq DESC LIMIT #{req.size} OFFSET #{offset}

SELECT COUNT(DISTINCT r.resume_sq) FROM TBL_RESUME_M r INNER JOIN TBL_USER_M u ON r.user_sq = u.user_sq
AND COALESCE( ( SELECT FLOOR(SUM(TIMESTAMPDIFF(MONTH, c.career_start_dt, COALESCE(c.career_end_dt, CURDATE()))) / 12) FROM TBL_RESUME_CAREER_S c WHERE c.resume_sq = r.resume_sq ), 0 ) >= #{req.experience}
AND r.resume_sq IN ( SELECT rss.resume_sq FROM TBL_RESUME_SKILL_SEARCH_S rss INNER JOIN TBL_SKILL_TAG_C st ON rss.skill_tag_sq = st.skill_tag_sq WHERE LOWER(st.skill_tag_nm) IN
LOWER(TRIM(#{skill}))
)
